import{_ as l,r as e,o as c,c as i,e as t,a as s,d as n,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Models - October CMS - 4.x","titleTemplate":false,"description":"Map the database table columns directly to a PHP object.","frontmatter":{"subtitle":"Map the database table columns directly to a PHP object."},"headers":[{"level":2,"title":"Defining Models","slug":"defining-models","link":"#defining-models","children":[{"level":3,"title":"Supported Properties","slug":"supported-properties","link":"#supported-properties","children":[{"level":4,"title":"Primary Key","slug":"primary-key","link":"#primary-key","children":[]},{"level":4,"title":"Incrementing","slug":"incrementing","link":"#incrementing","children":[]},{"level":4,"title":"Timestamps","slug":"timestamps","link":"#timestamps","children":[]},{"level":4,"title":"Values stored as JSON","slug":"values-stored-as-json","link":"#values-stored-as-json","children":[]}]}]},{"level":2,"title":"Model Events","slug":"model-events","link":"#model-events","children":[{"level":3,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]}]},{"level":2,"title":"Extending Models","slug":"extending-models","link":"#extending-models","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/system/models.md","filePath":"4.x/extend/system/models.md"}'),d={name:"4.x/extend/system/models.md"};function u(k,a,g,h,m,f){const o=e("pre-heading"),p=e("post-heading");return c(),i("div",null,[t(o),a[0]||(a[0]=s("h1",null,"Models",-1)),t(p),a[1]||(a[1]=s("p",null,[n("October CMS provides a beautiful and simple Active Record implementation for working with your database, based on "),s("a",{href:"http://laravel.com/docs/eloquent",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Eloquent by Laravel"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n('. Each database table has a corresponding "Model" which is used to interact with that table. Models allow you to query for data in your tables, as well as insert new records into the table.')],-1)),a[2]||(a[2]=r(`<p>Model classes reside in the <strong>models</strong> subdirectory of a plugin directory. An example of a model directory structure.</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>models</code>
|           |   ├── post  <em>← Config Directory</em>
|           |   |   ├── fields.yaml  <em>← Config File</em>
|           |   |   └── columns.yaml  <em>← Config File</em>
|           |   └── Post.php  <em>← Model Class</em>
|           └── Plugin.php</p>
</code></pre><p>The model configuration directory could contain the model&#39;s <a href="./../../element/form-fields.html">form field definitions</a>. The model configuration directory name matches the model class name written in lowercase.</p><h2 id="defining-models"><a href="#defining-models" class="header-anchor">#</a> Defining Models</h2><p>The <code>create:model</code> command generates the files needed for a new model. The first argument specifies the author and plugin name. The second argument specifies the model class name.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:model Acme.Blog Post
</code></pre></div><p>In most cases, you should create one model class for each database table. All model classes must extend the <code>Model</code> class. The most basic representation of a model used inside a Plugin looks like this.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$table</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_blog_posts&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>$table</code> protected field specifies the database table corresponding the model. The table name is a snake case name of the author, plugin and pluralized record type name.</p><h3 id="supported-properties"><a href="#supported-properties" class="header-anchor">#</a> Supported Properties</h3><p>There are some standard properties that can be found on models, in addition to those provided by <a href="./traits.html">model traits</a>. For example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;last_seen_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;permissions&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>$primaryKey</strong></td><td>primary key name used to identify the model.</td></tr><tr><td><strong>$incrementing</strong></td><td>boolean that if false indicates that the primary key is not an incrementing integer value.</td></tr><tr><td><strong>$exists</strong></td><td>boolean that if true indicates that the model exists.</td></tr><tr><td><strong>$dates</strong></td><td>values are converted to an instance of Carbon/DateTime objects after fetching.</td></tr><tr><td><strong>$timestamps</strong></td><td>boolean that if true will automatically set created_at and updated_at fields.</td></tr><tr><td><strong>$jsonable</strong></td><td>values are encoded as JSON before saving and converted to arrays after fetching.</td></tr><tr><td><strong>$fillable</strong></td><td>values are fields accessible to mass assignment.</td></tr><tr><td><strong>$guarded</strong></td><td>values are fields guarded from mass assignment.</td></tr><tr><td><strong>$visible</strong></td><td>values are fields made visible when <a href="./../database/serialization.html">serializing the model data</a>.</td></tr><tr><td><strong>$hidden</strong></td><td>values are fields made hidden when <a href="./../database/serialization.html">serializing the model data</a>.</td></tr><tr><td><strong>$connection</strong></td><td>string that contains the <a href="./../../setup/database-config.html">connection name</a> that&#39;s utilised by the model by default.</td></tr></tbody></table></div><h4 id="primary-key"><a href="#primary-key" class="header-anchor">#</a> Primary Key</h4><p>Models will assume that each table has a primary key column named <code>id</code>. You may define a <code>$primaryKey</code> property to override this convention.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="incrementing"><a href="#incrementing" class="header-anchor">#</a> Incrementing</h4><p>Models will assume that the primary key is an incrementing integer value, which means that by default the primary key will be cast to an integer automatically. If you wish to use a non-incrementing or a non-numeric primary key you must set the public <code>$incrementing</code> property to false.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Message</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$incrementing</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="timestamps"><a href="#timestamps" class="header-anchor">#</a> Timestamps</h4><p>By default, a model will expect <code>created_at</code> and <code>updated_at</code> columns to exist on your tables. If you do not wish to have these columns managed automatically, set the <code>$timestamps</code> property on your model to <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If you need to customize the format of your timestamps, set the <code>$dateFormat</code> property on your model. This property determines how date attributes are stored in the database, as well as their format when the model is serialized to an array or JSON.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$dateFormat</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;U&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="values-stored-as-json"><a href="#values-stored-as-json" class="header-anchor">#</a> Values stored as JSON</h4><p>When attributes names are passed to the <code>$jsonable</code> property, the values will be serialized and deserialized from the database as JSON.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="model-events"><a href="#model-events" class="header-anchor">#</a> Model Events</h2><p>Models fire several events, allowing you to hook into various points in the model&#39;s life cycle. Events allow you to easily execute code each time a specific model class is saved or updated in the database. Events are defined by overriding special methods in the class, the following method overrides are available:</p><div class="table"><table tabindex="0"><thead><tr><th>Event</th><th>Description</th></tr></thead><tbody><tr><td><strong>beforeCreate</strong></td><td>before the model is saved, when first created.</td></tr><tr><td><strong>afterCreate</strong></td><td>after the model is saved, when first created.</td></tr><tr><td><strong>beforeSave</strong></td><td>before the model is saved, either created or updated.</td></tr><tr><td><strong>afterSave</strong></td><td>after the model is saved, either created or updated.</td></tr><tr><td><strong>beforeValidate</strong></td><td>before the supplied model data is validated.</td></tr><tr><td><strong>afterValidate</strong></td><td>after the supplied model data has been validated.</td></tr><tr><td><strong>beforeUpdate</strong></td><td>before an existing model is saved.</td></tr><tr><td><strong>afterUpdate</strong></td><td>after an existing model is saved.</td></tr><tr><td><strong>beforeDelete</strong></td><td>before an existing model is deleted.</td></tr><tr><td><strong>afterDelete</strong></td><td>after an existing model is deleted.</td></tr><tr><td><strong>beforeRestore</strong></td><td>before a soft-deleted model is restored.</td></tr><tr><td><strong>afterRestore</strong></td><td>after a soft-deleted model has been restored.</td></tr><tr><td><strong>beforeFetch</strong></td><td>before an existing model is populated.</td></tr><tr><td><strong>afterFetch</strong></td><td>after an existing model has been populated.</td></tr></tbody></table></div><p>The following is an example of using an event.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h3><p>Whenever a new model is saved for the first time, the <code>beforeCreate</code> and <code>afterCreate</code> events will fire. If a model already existed in the database and the <code>save</code> method is called, the <code>beforeUpdate</code> / <code>afterUpdate</code> events will fire. However, in both cases, the <code>beforeSave</code> / <code>afterSave</code> events will fire.</p><p>For example, let&#39;s define an event listener that populates the <code>slug</code> attribute when a model is first created.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Returning <code>false</code> from an event will cancel the <code>save</code> / <code>update</code> operation.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">isValid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>It&#39;s possible to access old values using the <code>original</code> attribute. For example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">afterUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">!==</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">original</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Title has changed</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may find relationships created using <a href="./../database/relations.html">deferred bindings</a> (i.e: file attachments) are not available inside model events yet. To access them early, use the <code>withDeferred</code> database query method on the relation.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$avatar</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$gallery</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">gallery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withDeferred</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can externally bind to <a href="./../services/event.html">local events</a> for a single instance of a model using the <code>bindEvent</code> method. The event name should be the same as the method override name, prefixed with <code>model.</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeCreate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="extending-models"><a href="#extending-models" class="header-anchor">#</a> Extending Models</h2><p>Since models are <a href="./behaviors.html">equipped to use behaviors</a>, they can be extended with the static <code>extend</code> method. The method takes a closure and passes the model object into it.</p><p>Inside the closure you can add relations to the model. Here we extend the <code>User</code> model to include a profile (has one) relationship referencing the <code>Profile</code> model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">hasOne</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;profile&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token class-name static-context">Profile</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This approach can also be used to bind to local events, the following code listens for the <code>model.beforeSave</code> event.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Additionally, a few methods exist to extend protected model properties.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Add cast attributes</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addCasts</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;some_extended_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;int&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Add a date attribute</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDateAttribute</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Adds fillable or jsonable fields</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addFillable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;some_data&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Typically the best place to place code is within your <a href="./../extending.html">plugin registration file</a> <code>boot</code> method as this will be run on every request ensuring that the extensions you make to the model are available everywhere.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../database/model.html">Querying a Model</a></li><li><a href="./../database/traits.html">Model Traits</a></li></ul></div>`,55))])}const y=l(d,[["render",u]]);export{v as __pageData,y as default};
